<?php
if (!defined('ABSPATH')) { exit; }
function yb_sample_terms($id, $tax) { $terms=wp_get_post_terms($id,$tax); return is_wp_error($terms)?[]:$terms; }
function yb_sample_spec($product,$label) {
    $text=wp_strip_all_tags(preg_replace('~</(?:p|li|div|tr)>|<br\s*/?>~i',"\n",$product->get_description()));
    return preg_match('/(?:^|\n)\s*'.preg_quote($label,'/').'\s*:\s*([^\n]+)/i',$text,$m)?trim($m[1]):'';
}
function yb_sample_model($product) { $model=$product->get_attribute('model') ?: ($product->get_attribute('pa_model') ?: (yb_sample_spec($product,'Model') ?: yb_sample_spec($product,'Model Number'))); return strlen($model)<=80 && preg_match('/[0-9]/',$model) ? $model : ''; }
function yb_sample_name($product) { $model=yb_sample_model($product); $name=$product->get_name(); return $model && strcasecmp(trim($name),trim($model))===0 ? (yb_sample_spec($product,'Toilet Type') ?: $name) : $name; }
function yb_sample_photo($id) { $file=$id?get_attached_file($id):false; return $file && is_file($file) ? wp_get_attachment_url($id) : false; }
function yb_sample_card($product,$index=0) {
    $brands=yb_sample_terms($product->get_id(),'product_brand');$model=yb_sample_model($product);$photo=yb_sample_photo($product->get_image_id()); ?>
    <li class="yb-card" style="--reveal-delay:<?php echo (int)($index%6)*45; ?>ms"><a href="<?php echo esc_url(add_query_arg('design_sample','1',get_permalink($product->get_id()))); ?>">
    <div class="yb-card-media"><?php if($photo): ?><img src="<?php echo esc_url($photo); ?>" alt="<?php echo esc_attr($product->get_name()); ?>" loading="lazy"><?php else: ?><span class="yb-photo-symbol" aria-hidden="true">＋</span><span>Product photo coming soon</span><?php endif; ?><span class="yb-card-arrow" aria-hidden="true">→</span></div>
    <div class="yb-card-copy"><p class="yb-brand"><?php echo $brands?esc_html($brands[0]->name):'Product collection'; ?></p><h2><?php echo esc_html(yb_sample_name($product)); ?></h2><p class="yb-model"><?php echo $model ? 'Model · '.esc_html($model) : 'Model not provided'; ?></p><span class="yb-card-link">View product <span aria-hidden="true">→</span></span></div></a></li>
<?php }
$catalogue=get_post_type_archive_link('product');
if(!$catalogue){$catalogue=home_url('/?post_type=product');}
$sample_catalogue=add_query_arg('design_sample','1',$catalogue);
get_header(); ?>
<main id="main" class="wrap yb-review">
<div class="yb-review-note"><span><i aria-hidden="true"></i> DESIGN REVIEW · REAL CATALOGUE DATA</span><a href="<?php echo esc_url(remove_query_arg('design_sample')); ?>">Current layout →</a></div>
<?php if(is_singular('product')): while(have_posts()):the_post();$product=wc_get_product(get_the_ID());if(!$product){continue;}$brands=yb_sample_terms(get_the_ID(),'product_brand');$model=yb_sample_model($product);$name=yb_sample_name($product);$url=get_permalink();$photos=[];foreach(array_unique(array_merge([$product->get_image_id()],$product->get_gallery_image_ids())) as $image_id){$src=yb_sample_photo($image_id);if($src){$photos[$image_id]=$src;}}
?>
<nav class="yb-breadcrumb" aria-label="Breadcrumb"><a href="<?php echo esc_url($sample_catalogue); ?>">Catalogue</a><span aria-hidden="true">/</span><?php if($brands): ?><a href="<?php echo esc_url(add_query_arg(['design_sample'=>'1','filter_brand'=>$brands[0]->slug],$catalogue)); ?>"><?php echo esc_html($brands[0]->name); ?></a><span aria-hidden="true">/</span><?php endif; ?><span aria-current="page"><?php echo esc_html($product->get_name()); ?></span></nav>
<div class="yb-product-layout"><div class="yb-gallery" aria-label="Product gallery"><?php if($photos): ?><div class="yb-gallery-track"><?php foreach($photos as $id=>$photo): ?><figure id="photo-<?php echo (int)$id; ?>"><img src="<?php echo esc_url($photo); ?>" alt="<?php echo esc_attr($product->get_name()); ?>"></figure><?php endforeach; ?></div><?php if(count($photos)>1): ?><div class="yb-thumbnails"><?php foreach($photos as $id=>$photo): ?><a href="#photo-<?php echo (int)$id; ?>" aria-label="View product image <?php echo (int)$id; ?>"><img src="<?php echo esc_url($photo); ?>" alt=""></a><?php endforeach; ?></div><?php endif; ?><?php else: ?><div class="yb-gallery-placeholder"><span class="yb-placeholder-grid" aria-hidden="true">＋</span><p>Room for the real thing.</p><span>Product photography has not been supplied.</span></div><?php endif; ?></div>
<div class="yb-product-copy"><p class="yb-kicker"><?php echo $brands?esc_html($brands[0]->name).' / PRODUCT COLLECTION':'PRODUCT COLLECTION'; ?></p><h1><?php echo esc_html($name); ?></h1><?php if($model): ?><p class="yb-product-model">MODEL <strong><?php echo esc_html($model); ?></strong></p><?php endif; ?>
<?php if($product->get_short_description()): ?><div class="yb-product-intro"><?php echo wp_kses_post(wpautop($product->get_short_description())); ?></div><?php endif; ?>
<a class="yb-original" href="<?php echo esc_url($url); ?>">Original product page →</a></div></div>
<section class="yb-specifications" aria-labelledby="yb-spec-title"><div><p class="yb-kicker">THE DETAILS THAT MATTER</p><h2 id="yb-spec-title">Product information<span>.</span></h2><p>From the existing catalogue. Confirm current requirements with our team.</p></div><div><?php if($product->get_description()): ?><details open><summary>Description &amp; available specifications</summary><div class="yb-description"><?php echo wp_kses_post(wpautop($product->get_description())); ?></div></details><?php endif; ?><?php if($product->has_attributes()): ?><details open><summary>Product attributes</summary><?php wc_display_product_attributes($product); ?></details><?php endif; ?><?php if(!$product->get_description()&&!$product->has_attributes()): ?><p>No specifications are supplied for this product. Please enquire for details.</p><?php endif; ?></div></section>
<?php $related=$brands ? get_posts(['post_type'=>'product','post_status'=>'publish','posts_per_page'=>3,'post__not_in'=>[$product->get_id()],'fields'=>'ids','orderby'=>'title','order'=>'ASC','tax_query'=>[['taxonomy'=>'product_brand','field'=>'term_id','terms'=>[$brands[0]->term_id]]]]) : wc_get_related_products($product->get_id(),3);if($related): ?><section class="yb-related" aria-labelledby="yb-related-title"><div class="yb-section-heading"><div><p class="yb-kicker">KEEP EXPLORING</p><h2 id="yb-related-title">Related products<span>.</span></h2></div><a href="<?php echo esc_url($sample_catalogue); ?>">Explore catalogue →</a></div><ul class="yb-grid"><?php foreach($related as $i=>$id){$item=wc_get_product($id);if($item&&$item->is_visible()){yb_sample_card($item,$i);}} ?></ul></section><?php endif; ?>
<?php endwhile; else:
$get=function($key){return isset($_GET[$key])&&is_string($_GET[$key])?sanitize_text_field(wp_unslash($_GET[$key])):'';};
$q=$get('catalogue_q');$brand_slug=$get('filter_brand');$category_slug=$get('filter_category');$current=get_queried_object();
if($current instanceof WP_Term){if($current->taxonomy==='product_brand'&&!isset($_GET['filter_brand'])){$brand_slug=$current->slug;}if($current->taxonomy==='product_cat'&&!isset($_GET['filter_category'])){$category_slug=$current->slug;}}
$selected=[];$tax_query=['relation'=>'AND'];foreach(['product_brand'=>$brand_slug,'product_cat'=>$category_slug] as $tax=>$slug){if($slug){$term=get_term_by('slug',$slug,$tax);if($term){$selected[$tax]=$term;$tax_query[]=['taxonomy'=>$tax,'field'=>'term_id','terms'=>[$term->term_id],'include_children'=>true];}}}
$page=max(1,absint($get('sample_page')));$args=['post_type'=>'product','post_status'=>'publish','posts_per_page'=>12,'paged'=>$page,'s'=>$q,'orderby'=>'title','order'=>'ASC','tax_query'=>$tax_query];
$visibility=wc_get_product_visibility_term_ids();if(!empty($visibility['exclude-from-catalog'])){$args['tax_query'][]=['taxonomy'=>'product_visibility','field'=>'term_taxonomy_id','terms'=>[$visibility['exclude-from-catalog']],'operator'=>'NOT IN'];}
$items=new WP_Query($args);$filters=['design_sample'=>'1','catalogue_q'=>$q,'filter_brand'=>$brand_slug,'filter_category'=>$category_slug];
?>
<header class="yb-catalogue-heading"><div><p class="yb-kicker">MATERIALS FOR WHAT’S NEXT</p><h1>The product<br>collection<span>.</span></h1></div><p>Explore building materials, marine hardware and specialist fittings. Find the right starting point for your next project.</p></header>
<form class="yb-catalogue-form" action="<?php echo esc_url($catalogue); ?>" method="get"><input type="hidden" name="design_sample" value="1">
<div class="yb-search"><label for="yb-search">Find your product</label><div><input id="yb-search" type="search" name="catalogue_q" value="<?php echo esc_attr($q); ?>" placeholder="Search products, names or model numbers…"><button type="submit">Search <span aria-hidden="true">→</span></button></div></div>
<div class="yb-catalogue-layout"><aside class="yb-filters" aria-label="Product filters"><details class="yb-filter-shell" open><summary>Filters <span aria-hidden="true">＋</span></summary><div class="yb-filter-panel"><div class="yb-filter-panel-title"><h2>Refine your search</h2><button class="yb-drawer-close" type="button" aria-label="Close filters">×</button></div><p>Find a range that fits.</p>
<?php foreach(['product_brand'=>['Brands','filter_brand',$brand_slug],'product_cat'=>['Categories','filter_category',$category_slug]] as $tax=>$config):$terms=get_terms(['taxonomy'=>$tax,'hide_empty'=>true,'orderby'=>'name']);if(is_wp_error($terms)){continue;} ?>
<details class="yb-filter-group" <?php echo $tax==='product_brand'||$config[2]?'open':''; ?>><summary><?php echo esc_html($config[0]); ?><span><?php echo count($terms); ?></span></summary><div class="yb-filter-options"><label><input type="radio" name="<?php echo esc_attr($config[1]); ?>" value="" <?php checked($config[2],''); ?>>All <?php echo esc_html(strtolower($config[0])); ?></label><?php foreach($terms as $term): ?><label><input type="radio" name="<?php echo esc_attr($config[1]); ?>" value="<?php echo esc_attr($term->slug); ?>" <?php checked($config[2],$term->slug); ?>><span><?php echo esc_html($term->name); ?></span><small><?php echo (int)$term->count; ?></small></label><?php endforeach; ?></div></details>
<?php endforeach; ?>
<button class="yb-primary yb-apply" type="submit">Apply filters <span aria-hidden="true">→</span></button><a class="yb-clear" href="<?php echo esc_url($sample_catalogue); ?>">Clear filters</a></div></details></aside>
<div class="yb-results"><div class="yb-results-heading"><p><strong><?php echo (int)$items->found_posts; ?></strong> products <span>· Explore the collection</span></p></div>
<?php if($selected||$q): ?><div class="yb-chips" aria-label="Selected filters"><?php foreach($selected as $tax=>$term):$key=$tax==='product_brand'?'filter_brand':'filter_category';$remove=$filters;$remove[$key]=''; ?><a href="<?php echo esc_url(add_query_arg($remove,$catalogue)); ?>" aria-label="Remove <?php echo esc_attr($term->name); ?> filter"><?php echo esc_html($term->name); ?> <span aria-hidden="true">×</span></a><?php endforeach;if($q):$remove=$filters;$remove['catalogue_q']=''; ?><a href="<?php echo esc_url(add_query_arg($remove,$catalogue)); ?>" aria-label="Remove search filter">Search: <?php echo esc_html($q); ?> <span aria-hidden="true">×</span></a><?php endif; ?><a class="yb-clear" href="<?php echo esc_url($sample_catalogue); ?>">Clear filters</a></div><?php endif; ?>
<?php if($items->have_posts()): ?><ul class="yb-grid"><?php foreach($items->posts as $i=>$post){$item=wc_get_product($post->ID);if($item){yb_sample_card($item,$i);}} ?></ul><?php if($items->max_num_pages>1): ?><nav class="yb-pagination" aria-label="Catalogue pages"><?php echo paginate_links(['base'=>add_query_arg(array_merge($filters,['sample_page'=>'%#%']),$catalogue),'format'=>'','current'=>$page,'total'=>$items->max_num_pages,'prev_text'=>'←','next_text'=>'→']); ?></nav><?php endif; ?>
<?php else: ?><div class="yb-empty"><h2>No matching products.</h2><p>Try another search or clear your filters.</p><a class="yb-primary" href="<?php echo esc_url($sample_catalogue); ?>">View all products →</a></div><?php endif; ?></div></div></form>
<?php wp_reset_postdata();endif; ?>
</main><?php get_footer(); ?>
